import React from 'react';
import { cn } from '../../utils/cn';
import { useColorTheme } from '../../hooks/useColorTheme';
import { IMAGE_RESOLUTIONS, GEMINI_IMAGE_SIZES, GEMINI_IMAGE_SIZE_SUPPORTED_MODELS } from '../../utils/constants';
import { TextInput, TextArea, Select, Slider } from "src/components/molecules/form-controls";
import { IMAGE_PROVIDER_META } from '../../features/ai/providers/registry';
import { Button } from 'src/components/atoms/button';
import { SettingsCard, SettingsCardHeader, SettingsRow } from 'src/components/molecules/settings-card';
import ToggleSwitch from 'src/components/atoms/ToggleSwitch';
import { ProviderPicker } from 'src/components/molecules/ProviderPicker';
import { SegmentedControl } from 'src/components/molecules/SegmentedControl';
import { NumberStepper } from 'src/components/molecules/NumberStepper';
import ComfyUISettings from './ComfyUISettings';
import { PromptStyleRow } from 'src/components/molecules/PromptStyleRow';
import { CONTROLNET_FACE_PRESETS } from '../../features/ai/utils/sdWebuiUtils';

interface ImageGenerationSettingsProps {
  imageProvider: string;
  setImageProvider: (provider: string) => void;
  openaiApiKey: string;
  setOpenaiApiKey: (key: string) => void;
  wanApiKey: string;
  setWanApiKey: (key: string) => void;
  wanBaseUrl: string;
  setWanBaseUrl: (url: string) => void;
  wanImageModelList: { value: string; label: string }[];
  wanReferenceModel: string;
  setWanReferenceModel: (model: string) => void;
  wanReferenceModelList: { value: string; label: string }[];
  falApiKey: string;
  setFalApiKey: (key: string) => void;
  falImageModelList: { value: string; label: string }[];
  glmApiKey: string;
  setGlmApiKey: (key: string) => void;
  glmImageModelList: { value: string; label: string }[];
  sdWebuiApiUrl: string;
  setSdWebuiApiUrl: (url: string) => void;
  sdWebuiBatchSize: number;
  setSdWebuiBatchSize: (size: number) => void;
  fetchSdModels: () => void;
  sdWebuiModel: string;
  setSdWebuiModel: (model: string) => void;
  sdWebuiModels: { title: string; model_name: string }[];
  sdWebuiRefMode: string;
  setSdWebuiRefMode: (mode: string) => void;
  sdWebuiDenoising: number;
  setSdWebuiDenoising: (denoising: number) => void;
  sdWebuiControlnetModel: string;
  setSdWebuiControlnetModel: (model: string) => void;
  imageModel: string;
  setImageModel: (model: string) => void;
  imageModelList: { value: string; label: string }[];
  openaiImageModelList: { value: string; label: string }[];
  canFetchImageModels: boolean;
  fetchImageModels: () => void;
  imageGenPrompt: string;
  setImageGenPrompt: (prompt: string) => void;
  imageResolution: string;
  setImageResolution: (res: string) => void;
  geminiImageSize: string;
  setGeminiImageSize: (size: string) => void;
  portraitSaveSize: string;
  setPortraitSaveSize: (size: string) => void;
  portraitResizeEnabled: boolean;
  setPortraitResizeEnabled: (enabled: boolean) => void;
  imageSaveDirName: string;
  handleSelectDirectory: () => void;
  LS_SD_WEBUI_MODEL: string;
  videoModel: string;
  setVideoModel: (model: string) => void;
  videoModelSuggestions: string[];
}

const REF_MODE_OPTIONS = [
  { value: "none", label: "None" },
  { value: "img2img", label: "img2img" },
  { value: "controlnet", label: "ControlNet" },
  { value: "reactor", label: "Face swap" },
];

const ImageGenerationSettings: React.FC<ImageGenerationSettingsProps> = ({
  imageProvider,
  setImageProvider,
  openaiApiKey,
  setOpenaiApiKey,
  wanApiKey,
  setWanApiKey,
  wanBaseUrl,
  setWanBaseUrl,
  wanImageModelList,
  wanReferenceModel,
  setWanReferenceModel,
  wanReferenceModelList,
  falApiKey,
  setFalApiKey,
  falImageModelList,
  glmApiKey,
  setGlmApiKey,
  glmImageModelList,
  sdWebuiApiUrl,
  setSdWebuiApiUrl,
  sdWebuiBatchSize,
  setSdWebuiBatchSize,
  fetchSdModels,
  sdWebuiModel,
  setSdWebuiModel,
  sdWebuiModels,
  sdWebuiRefMode,
  setSdWebuiRefMode,
  sdWebuiDenoising,
  setSdWebuiDenoising,
  sdWebuiControlnetModel,
  setSdWebuiControlnetModel,
  imageModel,
  setImageModel,
  imageModelList,
  openaiImageModelList,
  canFetchImageModels,
  fetchImageModels,
  imageGenPrompt,
  setImageGenPrompt,
  imageResolution,
  setImageResolution,
  geminiImageSize,
  setGeminiImageSize,
  portraitSaveSize,
  setPortraitSaveSize,
  portraitResizeEnabled,
  setPortraitResizeEnabled,
  imageSaveDirName,
  handleSelectDirectory,
  LS_SD_WEBUI_MODEL,
  videoModel,
  setVideoModel,
  videoModelSuggestions,
}) => {
  const { is } = useColorTheme();
  return (
    <div className="flex flex-col gap-5">
      <SettingsCard>
        <div className="p-5 flex flex-col gap-3">
          <SettingsCardHeader title="Provider" hint="Chat and image providers are set independently" />
          <ProviderPicker providers={IMAGE_PROVIDER_META} value={imageProvider} onChange={setImageProvider} />
        </div>

        {imageProvider === 'comfyui' ? (
          <ComfyUISettings />
        ) : imageProvider === 'sdwebui' ? (
          <>
            <SettingsRow label="API URL" hint="Your local Forge / WebUI instance.">
              <TextInput
                type="text"
                value={sdWebuiApiUrl}
                onChange={(e) => setSdWebuiApiUrl(e.target.value)}
                placeholder="http://127.0.0.1:7860"
              />
            </SettingsRow>

            <SettingsRow
              label="SD model"
              hint={
                <Button
                  type="button"
                  variant="link"
                  onClick={fetchSdModels}
                  className="h-auto p-0 text-xs text-primary hover:text-primary-hover no-underline hover:no-underline"
                >
                  Refresh models
                </Button>
              }
            >
              <Select
                aria-label="SD WebUI checkpoint"
                value={sdWebuiModel}
                onChange={(e) => {
                  setSdWebuiModel(e.target.value);
                  localStorage.setItem(LS_SD_WEBUI_MODEL, e.target.value);
                }}
              >
                <option value="">Default (From SD WebUI)</option>
                {sdWebuiModels.map((m) => (
                  <option key={m.title} value={m.title}>
                    {m.model_name}
                  </option>
                ))}
              </Select>
            </SettingsRow>

            <SettingsRow label="Images per request" hint="1-8. Higher counts take longer.">
              <NumberStepper value={sdWebuiBatchSize} min={1} max={8} onChange={setSdWebuiBatchSize} />
            </SettingsRow>

            <SettingsRow label="Reference image mode" hint="How the character's appearance images are used." align="start">
              <SegmentedControl value={sdWebuiRefMode} onChange={setSdWebuiRefMode} options={REF_MODE_OPTIONS} />

              {sdWebuiRefMode === 'reactor' && (
                <div className="mt-3">
                  <p className="text-xs text-primary font-medium mb-1">
                    ReActor requires the "sd-webui-reactor-sfw" extension installed in Forge.
                  </p>
                  <p className="text-xs text-muted-foreground">
                    This passes the character image natively to inswapper to perform a highly accurate
                    post-process face swap over the generated subject.
                  </p>
                </div>
              )}

              {sdWebuiRefMode === 'img2img' && (
                <div className="mt-3">
                  <div className="flex justify-between text-xs text-subtle mb-2">
                    <span>Keep the reference</span>
                    <span className="text-foreground font-semibold tabular-nums">{sdWebuiDenoising}</span>
                    <span>Reimagine</span>
                  </div>
                  <Slider value={sdWebuiDenoising} min={0} max={1} step={0.05} onChange={setSdWebuiDenoising} />
                </div>
              )}

              {sdWebuiRefMode === 'controlnet' && (
                <div className="mt-3">
                  <TextInput
                    type="text"
                    value={sdWebuiControlnetModel}
                    onChange={(e) => setSdWebuiControlnetModel(e.target.value)}
                    placeholder="e.g. ip-adapter_sd15"
                    aria-label="ControlNet model"
                  />
                  <div className="mt-2 flex flex-wrap gap-2" role="group" aria-label="ControlNet presets">
                    {CONTROLNET_FACE_PRESETS.map((preset) => (
                      <Button
                        key={preset.model}
                        type="button"
                        size="sm"
                        variant={sdWebuiControlnetModel === preset.model ? 'default' : 'outline'}
                        aria-pressed={sdWebuiControlnetModel === preset.model}
                        onClick={() => setSdWebuiControlnetModel(preset.model)}
                      >
                        {preset.label}
                      </Button>
                    ))}
                  </div>
                  <p className="text-xs text-muted-foreground mt-1">
                    FaceID keeps the face itself; plain IP-Adapter copies the overall look. The matching preprocessor is picked for you. Make sure the model is installed in your Forge/WebUI.
                  </p>
                </div>
              )}
            </SettingsRow>
          </>
        ) : imageProvider === 'openai' ? (
          <>
            <SettingsRow label="API key" hint="Stored encrypted, only on this device.">
              <TextInput
                type="password"
                value={openaiApiKey}
                onChange={(e) => setOpenaiApiKey(e.target.value)}
                placeholder="Paste your API key here..."
              />
            </SettingsRow>

            <SettingsRow
              label="Model"
              hint={
                canFetchImageModels ? (
                  <Button
                    type="button"
                    variant="link"
                    onClick={fetchImageModels}
                    className="h-auto p-0 text-xs text-primary hover:text-primary-hover no-underline hover:no-underline"
                  >
                    Fetch available models
                  </Button>
                ) : (
                  'Used when "send pic" or similar is queried.'
                )
              }
            >
              <Select aria-label="Image model" value={imageModel} onChange={(e) => setImageModel(e.target.value)}>
                {openaiImageModelList.map((model) => (
                  <option key={model.value} value={model.value}>
                    {model.label}
                  </option>
                ))}
              </Select>
            </SettingsRow>
          </>
        ) : imageProvider === 'wan' ? (
          <>
            <SettingsRow label="API key" hint="Your DashScope (Alibaba Cloud Model Studio) key. Stored encrypted, only on this device.">
              <TextInput
                type="password"
                value={wanApiKey}
                onChange={(e) => setWanApiKey(e.target.value)}
                placeholder="Paste your API key here..."
              />
            </SettingsRow>

            <SettingsRow label="Workspace endpoint" hint="Your account's workspace-scoped endpoint from the Model Studio console, e.g. https://<workspace-id>.ap-southeast-1.maas.aliyuncs.com">
              <TextInput
                type="text"
                value={wanBaseUrl}
                onChange={(e) => setWanBaseUrl(e.target.value)}
                placeholder="https://<workspace-id>.ap-southeast-1.maas.aliyuncs.com"
              />
            </SettingsRow>

            <SettingsRow label="Model" hint={'Used when "send pic" or similar is queried. Generation is async and typically takes 1-2 minutes.'}>
              <Select aria-label="Image model" value={imageModel} onChange={(e) => setImageModel(e.target.value)}>
                {wanImageModelList.map((model) => (
                  <option key={model.value} value={model.value}>
                    {model.label}
                  </option>
                ))}
              </Select>
            </SettingsRow>

            <SettingsRow
              label="Model with reference photos"
              hint="Used instead when the character has appearance images, so their face stays the same. wan2.7-image takes up to 9 photos in every region; wan2.5-i2i-preview takes 3 and falls back to wan2.7-image if your region rejects it."
            >
              <Select aria-label="Wan model with reference photos" value={wanReferenceModel} onChange={(e) => setWanReferenceModel(e.target.value)}>
                {wanReferenceModelList.map((model) => (
                  <option key={model.value} value={model.value}>
                    {model.label}
                  </option>
                ))}
              </Select>
            </SettingsRow>
          </>
        ) : imageProvider === 'fal' ? (
          <>
            <SettingsRow label="API key" hint="Your fal.ai key (fal.ai/dashboard/keys). Stored encrypted, only on this device.">
              <TextInput
                type="password"
                aria-label="fal.ai API key"
                value={falApiKey}
                onChange={(e) => setFalApiKey(e.target.value)}
                placeholder="Paste your API key here..."
              />
            </SettingsRow>

            <SettingsRow
              label="Model"
              hint="The character's appearance images go to the model as references, so their face stays the same. Seedream takes several photos; FLUX Kontext and PuLID use the main one. Without photos, each model draws from the text alone."
            >
              <Select aria-label="fal.ai model" value={imageModel} onChange={(e) => setImageModel(e.target.value)}>
                {falImageModelList.map((model) => (
                  <option key={model.value} value={model.value}>
                    {model.label}
                  </option>
                ))}
              </Select>
            </SettingsRow>
          </>
        ) : imageProvider === 'glm' ? (
          <>
            <SettingsRow label="API key" hint="Your Z.ai (Zhipu AI) key. Stored encrypted, only on this device.">
              <TextInput
                type="password"
                value={glmApiKey}
                onChange={(e) => setGlmApiKey(e.target.value)}
                placeholder="Paste your API key here..."
              />
            </SettingsRow>

            <SettingsRow label="Model" hint={'Used when "send pic" or similar is queried.'}>
              <Select aria-label="Image model" value={imageModel} onChange={(e) => setImageModel(e.target.value)}>
                {glmImageModelList.map((model) => (
                  <option key={model.value} value={model.value}>
                    {model.label}
                  </option>
                ))}
              </Select>
            </SettingsRow>
          </>
        ) : (
          <SettingsRow label="Model" hint={'Used when "send pic" or similar is queried.'}>
            <Select aria-label="Image model" value={imageModel} onChange={(e) => setImageModel(e.target.value)}>
              {imageModelList.map((model) => (
                <option key={model.value} value={model.value}>
                  {model.label}
                </option>
              ))}
            </Select>
          </SettingsRow>
        )}

        <PromptStyleRow providerId={imageProvider} imageModel={imageModel} sdWebuiModel={sdWebuiModel} />
      </SettingsCard>

      <SettingsCard>
        <div className="p-5 flex flex-col gap-3">
          <SettingsCardHeader title="Video generation" hint="Wan (Wanxiang, via DashScope) is the only video provider today - independent of the image provider above, and used whenever a message requests a video." />
        </div>

        {imageProvider !== 'wan' && (
          <>
            <SettingsRow label="API key" hint="Your DashScope (Alibaba Cloud Model Studio) key. Stored encrypted, only on this device.">
              <TextInput
                type="password"
                value={wanApiKey}
                onChange={(e) => setWanApiKey(e.target.value)}
                placeholder="Paste your API key here..."
              />
            </SettingsRow>

            <SettingsRow label="Workspace endpoint" hint="Your account's workspace-scoped endpoint from the Model Studio console, e.g. https://<workspace-id>.ap-southeast-1.maas.aliyuncs.com">
              <TextInput
                type="text"
                value={wanBaseUrl}
                onChange={(e) => setWanBaseUrl(e.target.value)}
                placeholder="https://<workspace-id>.ap-southeast-1.maas.aliyuncs.com"
              />
            </SettingsRow>
          </>
        )}

        <SettingsRow label="Model" hint="Free text - Wan's exact model naming shifts between releases, so pick one of these suggestions or paste the exact id from the Model Studio console. Generation is async and typically takes 1-5+ minutes.">
          <TextInput
            type="text"
            list="wan-video-model-options"
            value={videoModel}
            onChange={(e) => setVideoModel(e.target.value)}
            placeholder="e.g. wan2.6-t2v"
          />
          <datalist id="wan-video-model-options">
            {videoModelSuggestions.map((m) => (
              <option key={m} value={m} />
            ))}
          </datalist>
        </SettingsRow>
      </SettingsCard>

      <SettingsCard>
        <div className="p-5">
          <SettingsCardHeader title="Output" />
        </div>

        <SettingsRow label="Base prompt" hint="Prepended whenever an image is requested." align="start">
          <TextArea
            value={imageGenPrompt}
            onChange={(e) => setImageGenPrompt(e.target.value)}
            placeholder="e.g. Create a high quality, detailed image..."
          />
        </SettingsRow>

        {imageProvider === 'sdwebui' && (
          <SettingsRow label="Default resolution">
            <SegmentedControl
              value={imageResolution}
              onChange={setImageResolution}
              options={IMAGE_RESOLUTIONS.map((res) => ({ value: res, label: res }))}
            />
          </SettingsRow>
        )}

        {imageProvider === 'gemini' && GEMINI_IMAGE_SIZE_SUPPORTED_MODELS.includes(imageModel) && (
          <SettingsRow label="Image size" hint="Higher sizes cost more and take longer. Applies to this model's generations, including character portraits.">
            <SegmentedControl
              value={geminiImageSize}
              onChange={setGeminiImageSize}
              options={GEMINI_IMAGE_SIZES.map((size) => ({ value: size, label: size }))}
            />
          </SettingsRow>
        )}

        <SettingsRow label="Resize portraits on save" hint="When off, portraits saved without an interactive crop step (PNG card imports, batch 'generate all emotions', and the quick in-chat missing-emotion generate) keep their native resolution instead of being resized below.">
          <ToggleSwitch checked={portraitResizeEnabled} onChange={setPortraitResizeEnabled} label={<span className="sr-only">Resize portraits on save</span>} />
        </SettingsRow>

        <SettingsRow label="Portrait save size" hint="Every character portrait - main avatar and emotion portraits alike, generated or uploaded - is resized to this before being saved, regardless of what resolution it came in at.">
          {(() => {
            const [w, h] = portraitSaveSize.split("x").map((n) => parseInt(n, 10) || 0);
            const clamp = (n: number) => Math.max(32, Math.min(2048, n));
            return (
              <div className={cn("flex items-center gap-2", !portraitResizeEnabled && "opacity-50")}>
                <TextInput
                  type="number"
                  aria-label="Portrait width"
                  min="32"
                  max="2048"
                  value={w}
                  disabled={!portraitResizeEnabled}
                  onChange={(e) => setPortraitSaveSize(`${clamp(Number(e.target.value))}x${h}`)}
                  className="w-24"
                />
                <span className="text-muted-foreground text-sm">×</span>
                <TextInput
                  type="number"
                  aria-label="Portrait height"
                  min="32"
                  max="2048"
                  value={h}
                  disabled={!portraitResizeEnabled}
                  onChange={(e) => setPortraitSaveSize(`${w}x${clamp(Number(e.target.value))}`)}
                  className="w-24"
                />
                <span className="text-xs text-subtle">px</span>
              </div>
            );
          })()}
        </SettingsRow>

        <SettingsRow label="Save generated images to" hint="Browsers may ask you to re-approve write access when you return.">
          <div className="flex items-center gap-2.5">
            <div className={cn("flex-1 h-10 rounded-lg bg-background border border-input flex items-center px-3 text-sm truncate", is("aurora") && "surface-sunken")}>
              {imageSaveDirName}
            </div>
            <Button onClick={handleSelectDirectory} variant="outline" className="whitespace-nowrap">
              Change folder
            </Button>
          </div>
        </SettingsRow>
      </SettingsCard>
    </div>
  );
};

export default ImageGenerationSettings;
